'use strict';
let S=null,csrf='',page='Overview',tab='',piDraft=null,recipeDraft=null,lastCalc=null,piFilter='Awaiting LC';
let securityEnrollment=null,securityRecoveryCodes=[],mfaSetupRequired=false,securityUser=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,n=2)=>Number(v||0).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),can=p=>S?.permissions.includes(p),btn=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`,badge=s=>`<span class="badge ${s==='Draft'?'grey':s==='Cancelled'?'red':s==='Awaiting LC'?'amber':''}">${esc(s)}</span>`,options=(items,value,label,selected)=>items.map(x=>`<option value="${esc(x[value])}" ${String(x[value])===String(selected)?'selected':''}>${esc(typeof label==='function'?label(x):x[label])}</option>`).join('');
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" value="${esc(value)}" type="${type}" ${type==='number'?(extra.includes('data-signed')?'step="any"':'step="any" min="0"'):''} ${extra}></label>`}
function select(label,name,items,selected,extra=''){return `<label class="field">${label}<select name="${name}" ${extra}>${items.map(x=>`<option value="${esc(Array.isArray(x)?x[0]:x)}" ${String(Array.isArray(x)?x[0]:x)===String(selected)?'selected':''}>${esc(Array.isArray(x)?x[1]:x)}</option>`).join('')}</select></label>`}
const textarea=(label,name,value='')=>`<label class="field span-all">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
const panel=(title,subtitle,body,action='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">◇</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}">${empty('No records yet','Your saved records will appear here.')}</td></tr>`}</tbody></table></div>`}
const scopedSearchQueries=new Map();
function searchTokens(query){return String(query||'').normalize('NFKC').toLocaleLowerCase().trim().split(/\s+/u).filter(Boolean)}
function matchesSearch(text,query){const normalized=String(text||'').normalize('NFKC').toLocaleLowerCase().replace(/\s+/gu,' ');return searchTokens(query).every(token=>normalized.includes(token))}
function bindScopedSearch(){
 const main=$('#main');if(!main)return;
 main.querySelectorAll('.table-wrap').forEach((wrap,index)=>{
  if(wrap.closest('form,.print-sheet')||wrap.querySelector('.scoped-search'))return;
  const table=wrap.querySelector('table'),body=table?.querySelector('tbody');if(!body)return;
  const records=Array.from(body.children).filter(row=>row.tagName==='TR'&&!row.querySelector('.empty'));
  records.forEach((row,i)=>row.dataset.searchIndex=String(i));
  const scope=wrap.closest('.panel')?.querySelector('h2')?.textContent||main.querySelector('h1')?.textContent||tab||page;
  const key=JSON.stringify([page,tab,page==='Proforma Invoices'?piFilter:'',scope,index]);
  const controls=document.createElement('div');controls.className='scoped-search no-print';
  const label=document.createElement('label');label.className='scoped-search-label';label.textContent='Search in '+scope;
  const input=document.createElement('input');input.type='search';input.className='search';input.placeholder='Search '+scope+'…';input.autocomplete='off';input.value=scopedSearchQueries.get(key)||'';label.append(input);
  const clear=document.createElement('button');clear.type='button';clear.className='small-btn';clear.textContent='Clear';clear.setAttribute('aria-label','Clear search in '+scope);
  const status=document.createElement('span');status.className='muted search-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');
  controls.append(label,clear,status);wrap.prepend(controls);
  const noMatch=document.createElement('tr');noMatch.className='search-empty no-print';noMatch.hidden=true;
  const cell=document.createElement('td');cell.colSpan=table.querySelectorAll('thead th').length;cell.className='search-empty-message';cell.textContent='No matching records in '+scope+'. Try another search or clear the search.';noMatch.append(cell);body.append(noMatch);
  function apply(){const query=input.value;let count=0;for(const row of records){row.hidden=!matchesSearch(row.textContent,query);if(!row.hidden)count++}noMatch.hidden=!records.length||count>0;clear.disabled=!query;status.textContent=count+' of '+records.length+' records';if(query)scopedSearchQueries.set(key,query);else scopedSearchQueries.delete(key)}
  input.addEventListener('input',apply);clear.addEventListener('click',()=>{input.value='';apply();input.focus()});apply();
 });
}
function visibleReportRows(){const table=$('#main .table-wrap table');if(!table)return reportRows;return Array.from(table.querySelectorAll('tbody tr[data-search-index]')).filter(row=>!row.hidden).map(row=>reportRows[Number(row.dataset.searchIndex)]).filter(Boolean)}
function notice(text,warning=false){return `<div class="notice ${warning?'warning':''}">${text}</div>`}
function head(title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">SATATA · PACKAGING WORKSPACE</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${action}</div></div>`}
function tabs(items){return `<div class="tabs">${items.map(t=>btn(esc(t),'tab',tab===t?'active':'',`data-tab="${esc(t)}"`)).join('')}</div>`}
async function api(path,data,key){let r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,'Idempotency-Key':key||crypto.randomUUID()},body:JSON.stringify(data)});let j=await r.json();if(!r.ok){let e=new Error(j.error||'Request failed');e.details=j;e.status=r.status;if(r.status===401&&S){S=null;auth(false)}if(j.mfa_enrollment_required){securityUser=S?.user||securityUser;S=null;mfaSetupRequired=true;showSecurity()}throw e}return j}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function showError(error,form){let text=error.message;if(error.details?.shortages)text+='\n'+error.details.shortages.map(x=>`${x.material}: ${fmt(x.shortage,6)} KG shortage`).join('\n');let el=form?.querySelector('.error');if(el){el.textContent=text;el.hidden=false}else toast(text)}
async function refresh(){S=await api('/api/state');render()}
function modal(title,body,submit='',id='generic-form'){let d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${btn('×','close','close','aria-label="Close dialog"')}</div><form id="${id}"><div class="dialog-body">${body}<div class="error" hidden></div></div>${submit?`<div class="form-footer">${btn('Cancel','close')}<button class="primary" type="submit">${submit}</button></div>`:''}</form>`;d.showModal()}
function close(){$('#dialog').close()}
function auth(setup,tokenRequired=false){scopedSearchQueries.clear();securityEnrollment=null;securityRecoveryCodes=[];mfaSetupRequired=false;securityUser=null;$('#app').innerHTML=`<div class="auth"><section class="auth-story"><div class="brand"><span class="brand-mark">s</span>satata <small>ERP</small></div><h1>Your packaging business.<br>Connected, from the start.</h1><p>From a verified recipe to a proforma invoice. From stock batches to collections. A clearer view of every detail.</p><small>PACKAGING · INVENTORY · TRADE FINANCE</small></section><section class="auth-form"><div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h1>${setup?'Set up your workspace':'Welcome back'}</h1><p>${setup?'Create your administrator account to get started.':'Sign in to access your business workspace.'}</p><form id="auth-form" data-setup="${setup}">${setup?field('Full name','name','','text','required autocomplete="name"'):''}${field('Username','username','','text','required autocomplete="username"')}${field('Password'+(setup?' · 15–128 characters':''),'password','','password','required '+(setup?'minlength="15" maxlength="128" ':'')+'autocomplete="'+(setup?'new-password':'current-password')+'"')}${setup&&tokenRequired?field('First administrator setup token','setup_token','','password','required autocomplete="off"'):''}${!setup?field('Authenticator / recovery code (if enabled)','code','','text','autocomplete="one-time-code" maxlength="32"'):''}<div class="error" hidden></div><button class="primary">${setup?'Create workspace':'Sign in'} →</button></form><p class="currency-note">Local workspace · Records are saved to your database.<br>No sample financial or stock transactions are preloaded.</p></section></div>`}
function showSecurity(){if(mfaSetupRequired){$('#app').innerHTML=`<main class="security-setup">${securityView()}<div class="form-footer">${btn('Sign out','logout')}</div></main>`}else{page='Account security';render()}}
function securityView(){const enabled=!!S?.security?.mfa_enabled;return head('Account security','Protect your sign-in and manage authenticator verification.')+(mfaSetupRequired?notice('Enable authenticator verification to finish securing the Admin account. Business records remain locked until verification.',true):'')+(securityRecoveryCodes.length?panel('Save your recovery codes','These single-use codes are shown only now. Store them somewhere private.',`<div class="panel-body">${notice('Each recovery code can be used once with your password if your authenticator is unavailable.')}<pre class="formula-preview">${securityRecoveryCodes.map(esc).join('\n')}</pre>${btn('Download recovery codes','download-recovery','small-btn')} ${btn('I saved these codes · hide','hide-recovery','small-btn')}</div>`):'')+panel('Authenticator verification',enabled?'Enabled · a current authenticator or unused recovery code is required when signing in.':'Use an authenticator app with manual setup. Your setup key is never sent to a QR-code service.',enabled&&!securityEnrollment?`<div class="panel-body">${badge('Enabled')}<p class="currency-note">Keep your authenticator and recovery codes private. Administrators cannot bypass this verification when resetting a password.</p></div><form id="mfa-enroll-form"><div class="panel-body form-grid two">${field('Current password','current_password','','password','required autocomplete="current-password"')}${field('Fresh authenticator / unused recovery code','code','','text','required maxlength="32" autocomplete="one-time-code"')}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Replace authenticator and recovery codes</button></div></form>`:securityEnrollment?`<form id="mfa-confirm-form"><div class="panel-body form-grid two">${field('Authenticator setup key · enter privately in your app','setup_secret',securityEnrollment.secret,'text','readonly')}${field('Account / issuer','issuer',(securityUser?.username||S?.user.username||'')+' / Satata ERP','text','readonly')}${field('Current 6-digit authenticator code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')}<div class="error span-all" hidden></div></div><div class="form-footer">${btn('Restart setup','mfa-restart')}<button class="primary">Verify and enable authenticator</button></div></form>`:`<form id="mfa-enroll-form"><div class="panel-body form-grid two">${field('Current password','current_password','','password','required autocomplete="current-password"')}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Set up authenticator</button></div></form>`)+(mfaSetupRequired?'':`<form id="password-form">${panel('Change password','Changing your password signs out other devices.',`<div class="panel-body form-grid two">${field('Current password','current_password','','password','required autocomplete="current-password"')}${field('New password · 15–128 characters','new_password','','password','required minlength="15" maxlength="128" autocomplete="new-password"')}${enabled?field('Fresh authenticator / recovery code','code','','text','required maxlength="32" autocomplete="one-time-code"'):''}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Change password</button></div>`)}</form>`)}
const MENU=[['Overview','▦'],['Proforma Invoices','▤'],['Customers','♧'],['MANUFACTURING','⚒'],['INVENTORY & STOCK','▧'],['Trade Finance','▥'],['Reports','▩'],['Administration','⚙']];
function render(){if(!S)return;$('#app').innerHTML=`<div class="app-shell"><aside><div class="brand"><span class="brand-mark">s</span>satata <small>ERP</small></div><div class="workspace"><span class="square">S</span><span>Satata Packaging<small>Business workspace</small></span></div><div class="nav-label">WORKSPACE</div><nav>${MENU.map(([m,i])=>btn(`<i>${i}</i>${m}`,'nav',page===m?'active':'',`data-page="${m}" title="${m}"`)).join('')}</nav><div class="side-note">Built around your business.<br>Every detail, accounted for.</div><div class="user"><span class="avatar">${esc(S.user.name.slice(0,2).toUpperCase())}</span><div>${esc(S.user.name)}<small>${esc(S.user.role)}</small></div>${btn('↗','logout','link','title="Sign out"')}</div></aside><div class="shell"><header><div>Workspace <span class="slash">/</span><span class="crumb">${esc(page)}</span></div><div class="header-right"><span class="connected">${S.company.name.startsWith('DEMO')?'DEMO workspace':'Database connected'}</span><time>${new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',day:'numeric',month:'short',year:'numeric'}).format(new Date())}</time>${btn('Security','account-security','small-btn','aria-label="Account security"')}<span class="avatar">${esc(S.user.name.slice(0,2).toUpperCase())}</span></div></header><main id="main">${content()}</main><footer><span>SATATA ERP · Local workspace</span><span>Clarity in every calculation.</span></footer></div></div>`;bindPage();bindScopedSearch()}
function content(){switch(page){case'Overview':return overview();case'Proforma Invoices':return proformas();case'Customers':return customers();case'MANUFACTURING':return manufacturing();case'INVENTORY & STOCK':return inventory();case'Trade Finance':return finance();case'Reports':return reports();case'Administration':return admin();case'Account security':return securityView()+'<div class="form-footer">'+btn('Sign out','logout')+'</div>';default:return''}}
function stat(label,value,foot,icon){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function overview(){let awaiting=S.pis.filter(x=>x.status==='Awaiting LC').length,confirmed=S.lcs.filter(x=>x.status==='Confirmed'),due=confirmed.filter(x=>Number(x.outstanding)>0),ready=S.recipes.filter(x=>x.validated).length;return head('Dashboard','A clear view of your business, all in one place.',can('pi')?btn('+ Create Proforma','create-pi','primary'):'')+`<div class="stats">${stat('Proforma invoices',S.pis.length,`<b>${awaiting} awaiting LC</b> · ${S.pis.filter(x=>x.status==='Draft').length} drafts`,'▤')}${stat('Active letters of credit',confirmed.length,`${due.length} with outstanding balances`,'▥')}${stat('Stock on hand',fmt(S.batches.reduce((n,b)=>n+Number(b.on_hand),0),1)+'<small> KG</small>',`${S.batches.length} batches · ${S.materials.length} materials`,'▧')}${stat('Customer directory',S.customers.length,'Your business relationships, connected','♧')}</div><div class="grid-two">${panel('Proforma overview','A simple path from calculation to collection',`<div class="workflow"><div class="step"><b>${S.pis.filter(x=>x.status==='Draft').length}</b>Draft</div><div class="step"><b>${awaiting}</b>Awaiting LC</div><div class="step"><b>${S.pis.filter(x=>x.status==='LC Created').length}</b>LC Created</div></div>${piTable(S.pis.slice(0,4),false)}`,btn('View register →','go-register','link'))}${panel('Collections at a glance','Outstanding amounts by currency',`<div class="panel-body">${['USD','BDT'].map(cur=>{let amount=due.filter(x=>x.currency===cur).reduce((n,x)=>n+Number(x.outstanding),0);return `<div class="amount-split"><span>${cur} outstanding</span><b>${cur==='USD'?'$':'৳'} ${fmt(amount)}</b></div>`}).join('')}<p class="currency-note">Currencies remain separate. No unsaved conversion rates.</p><div class="amount-split"><span>Upcoming maturities</span><b>${due.filter(x=>x.details.maturity_date&&x.details.maturity_date>=today()).length}</b></div></div>`,btn('Trade finance →','go-finance','link'))}</div><div class="grid-two">${panel('Workspace readiness','Set up once. Use across every invoice.',`<div class="checklist">${[['Customer directory',S.customers.length>0,'Customers'],['Material batches',S.batches.length>0,'INVENTORY & STOCK'],['Verified recipe samples',ready>0,'MANUFACTURING'],['Company & print settings',!!S.company.name,'Administration']].map(([label,ok,target])=>`<div class="check-row"><span class="check-circle">${ok?'✓':'○'}</span>${label}${btn(ok?'Review →':'Set up →','nav','link',`data-page="${target}"`)}</div>`).join('')}</div>`)}${panel('Recent activity','The latest saved changes',S.audit.length?`<div class="activity">${S.audit.slice(0,5).map(x=>`<div class="activity-row"><span class="a-icon">✓</span><div>${esc(x.action)}<small>${esc(x.actor)}</small></div><time>${esc(x.created.slice(11,16))} UTC</time></div>`).join('')}</div>`:empty('Your workspace is ready','Activity appears as records are saved.'))}</div>`}
function piTable(items,actions=true){return table(['PI number','Customer','Amount','Status',actions?'Actions':'Revision'],items.map(p=>`<tr><td>${btn(`<strong>${esc(p.number)}</strong>`,'preview','link',`data-id="${p.id}"`)}<small>${esc(p.snapshot.date)}</small></td><td>${esc(p.snapshot.customer.name)}</td><td>${p.currency} ${fmt(p.total)}</td><td>${badge(p.status)}</td><td>${actions?`<div class="table-actions">${btn('Preview','preview','small-btn',`data-id="${p.id}"`)}${can('approve')&&p.status==='Draft'?btn('Approve','approve','small-btn',`data-id="${p.id}"`):''}${can('finance')&&p.status==='Awaiting LC'?btn('Add LC','add-lc','small-btn',`data-id="${p.id}"`):''}</div>`:'v'+p.revision}</td></tr>`).join(''))}
function proformas(){if(tab==='Create Proforma'||tab==='Unit Price Calculation')return piEditor();if(tab==='Preview')return piPreview();tab='PI Register';let filters=['Awaiting LC','LC Created','All Proformas','Cancelled'];let items=S.pis.filter(p=>piFilter==='All Proformas'||p.status===piFilter);return head('Proforma Invoices','Calculate with confidence. Keep every revision.',can('pi')?btn('+ Create Proforma','create-pi','primary'):'')+tabs(['PI Register','Unit Price Calculation'])+`<div class="tabs">${filters.map(f=>btn(esc(f),'pi-filter',piFilter===f?'active':'',`data-filter="${f}"`)).join('')}</div>`+notice('Drafts appear under All Proformas. Approved proformas enter Awaiting LC; only a confirmed LC moves them to LC Created.')+panel('PI Register',`${items.length} proforma${items.length===1?'':'s'}`,piTable(items))}
function customers(){return head('Customers','Your customer directory and complete business profiles.',can('customer')?btn('+ Add customer','customer-new','primary'):'')+panel('Customer Directory',`${S.customers.length} customers`,table(['Customer','Contact','Phone','Email','Profile'],S.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.address)}</small></td><td>${esc(c.contact)}</td><td>${esc(c.phone)}</td><td>${esc(c.email)}</td><td>${btn('View profile →','customer-profile','link',`data-id="${c.id}"`)}</td></tr>`).join('')))}
function customerForm(c={}){modal(c.id?'Edit customer':'Add customer',`<div class="form-grid two">${field('Customer / applicant name','name',c.name,'text','required')}${field('Contact person','contact',c.contact)}${field('Email','email',c.email,'email')}${field('Phone','phone',c.phone)}${textarea('Address','address',c.address)}<input type="hidden" name="id" value="${c.id||''}"></div>`,'Save customer','customer-form')}
function customerProfile(id){let c=S.customers.find(x=>x.id===id),pis=S.pis.filter(x=>x.customer_id===id);modal('Customer Profile',`<h2>${esc(c.name)}</h2><p>${esc(c.address)}</p><div class="detail-meta"><div><small>CONTACT</small>${esc(c.contact)}</div><div><small>EMAIL</small>${esc(c.email)}</div><div><small>PHONE</small>${esc(c.phone)}</div></div>${can('customer')?btn('Edit profile','customer-edit','small-btn',`data-id="${id}"`):''}<h3>Proforma history</h3>${piTable(pis,false)}`)}
const sampleDefaults={l:'60',w:'40',h:'45',liner_gsm:'150',medium_gsm:'120',gsm:'150',quantity:'1',currency:'BDT',fx:'1',markup:'0'};
const GSM_FIELDS=[['liner_gsm','Liner paper · GSM'],['medium_gsm','Medium paper · GSM'],['gsm','GSM']];
function requiredGsms(config){return new Set((config?.components||[]).filter(c=>c.kind==='paper').map(c=>c.gsm))}
function gsmFields(config,data){let used=requiredGsms(config);return GSM_FIELDS.map(([name,label])=>field(label,name,data[name]??'','number',used.has(name)?'required':'').replace('</label>',`<small data-gsm-hint="${name}">${used.has(name)?'Required by this recipe':'Optional · not used by this recipe'}</small></label>`)).join('')}
function updateGsmRequirements(form,config){let used=requiredGsms(config);for(let [name] of GSM_FIELDS){let input=form.querySelector(`[name="${name}"]`),hint=form.querySelector(`[data-gsm-hint="${name}"]`);if(input)input.required=used.has(name);if(hint)hint.textContent=used.has(name)?'Required by this recipe':'Optional · not used by this recipe'}}
function calcFields(data={},recipe=true){let d={...sampleDefaults,...(recipe?{liner_gsm:'',medium_gsm:'',gsm:''}:{}),...data},selected=recipe?S.recipes.find(r=>r.id===Number(d.recipe_id))||S.recipes[0]:S.recipes.find(r=>r.id===recipeDraft?.id);return `${recipe?select('Product & recipe version','recipe_id',S.recipes.map(r=>[r.id,S.products.find(p=>p.id===r.product_id)?.name+' · v'+r.version+(r.validated?' · verified':' · sample required')]),d.recipe_id):''}${field('Length L1 · CM','l',d.l,'number','required min="0.001"')}${field('Width W1 · CM','w',d.w,'number','required min="0.001"')}${field('Height H1 · CM','h',d.h,'number','required min="0.001"')}${gsmFields(selected?.config,d)}${field('Quantity · PCS','quantity',d.quantity,'number','required min="1"')}${field('Markup · %','markup',d.markup,'number','required')}`}
function piEditor(){if(!can('pi'))return head('Unit Price Calculation','Your role does not have invoice editing permissions.');piDraft??={lines:[],currency:'BDT',fx:'1',date:today(),payment_terms:'',customer_id:S.customers[0]?.id};let d=piDraft;return head(d.id?'Revise Proforma':'Create Proforma','Product inputs → verified recipe → FIFO batch costing → automatic unit price.',btn('← PI Register','go-register'))+notice('Dimensions are in CM. Costing uses available FIFO batches without reducing physical stock. Each input change requires recalculation.')+`<form id="pi-form"><section class="panel form-section"><div class="section-title">01 · COMPANY & INVOICE DETAILS</div><div class="section-body form-grid">${select('Applicant / customer','customer_id',S.customers.map(x=>[x.id,x.name]),d.customer_id,'required')}${field('Beneficiary','beneficiary',S.company.name,'text','readonly')}${field('PI date','date',d.date,'date','required')}${select('Currency','currency',['BDT','USD'],d.currency)}${field('Exchange rate · BDT per USD','fx',d.fx,'number','required')}${field('PO number','po_number',d.po_number)}${textarea('Payment terms / duration','payment_terms',d.payment_terms)}${textarea('Additional notes','notes',d.notes)}</div></section><section class="panel form-section"><div class="section-title">02 · PRODUCT & UNIT PRICE CALCULATION</div><div class="section-body"><div class="form-grid" id="calc-inputs">${calcFields(d.calc||{})}${field('Unit Price · automatic','unit_price',lastCalc?.unit_price||'','text','readonly')}${field('H.S code','hs_code',d.hs_code||'')}</div><div class="form-footer">${btn('Calculate Unit Price','calculate','primary')}${btn('+ Add calculated line','add-line','',lastCalc?.ready?'':'disabled')}</div><div id="calc-result">${lastCalc?calcResult(lastCalc):''}</div></div></section><section class="panel form-section"><div class="section-title">03 · PI LINE ITEMS</div>${table(['Product','Size · CM','Quantity','Unit Price','Amount',''],d.lines.map((l,i)=>`<tr><td>${esc(l.product)}<small>Recipe v${l.result.recipe_version}</small></td><td>${l.inputs.l} × ${l.inputs.w} × ${l.inputs.h}</td><td>${fmt(l.inputs.quantity,0)} PCS</td><td>${d.currency} ${fmt(l.result.unit_price,6)}</td><td>${fmt(Number(l.result.unit_price)*Number(l.inputs.quantity))}</td><td>${btn('Remove','remove-line','link',`data-index="${i}"`)}</td></tr>`).join(''))}<div class="panel-body right"><h2>Total: ${d.currency} ${fmt(d.lines.reduce((n,l)=>n+Number((Number(l.result.unit_price)*Number(l.inputs.quantity)).toFixed(2)),0))}</h2></div><div class="form-footer"><span class="muted">Number assigned on save · ${d.id?'New revision, approval required':'Saved as draft'}</span><button class="primary" type="submit" ${d.lines.length?'':'disabled'}>Save ${d.id?'revision':'Proforma'}</button></div><div class="error" hidden></div></section></form>`}
function calcResult(r){return `${r.blockers?.length?notice(r.blockers.map(esc).join('<br>'),true):notice('Calculation complete. Unit Price filled automatically. Add this calculated line to your PI.')}<div class="formula-preview">Paper dimensions: ${Object.entries(r.dimensions).map(([k,v])=>k+' = '+fmt(v,2)+' CM').join(' · ')}<br>Recipe version ${r.recipe_version} · FIFO allocation · ${r.currency} · FX ${r.fx}</div>${table(['Raw material','Per piece · KG','Required · KG','Weighted cost · BDT/KG','Cost · BDT'],r.materials.map(x=>`<tr><td>${esc(x.material)}<small>${x.allocations.map(a=>esc(a.boe)+' / '+esc(a.batch)).join(', ')}</small></td><td>${fmt(x.per_piece,8)}</td><td>${fmt(x.required,6)}</td><td>${x.weighted_unit_cost_bdt?fmt(x.weighted_unit_cost_bdt,6):'—'}</td><td>${fmt(x.cost_bdt)}</td></tr>`).join(''))}${r.shortages.length?table(['Material','Required KG','Shortage KG'],r.shortages.map(x=>`<tr><td>${esc(x.material)}</td><td>${fmt(x.required,6)}</td><td>${fmt(x.shortage,6)}</td></tr>`).join('')):''}`}
function piPreview(){let p=S.pis.find(x=>x.id===Number(piDraft?.previewId));if(!p){tab='PI Register';return proformas()}let version=piDraft.previewRevision?p.history.find(h=>h.revision===Number(piDraft.previewRevision)):null,s=version?.snapshot||p.snapshot,total=version?.total||p.total;return head(p.number,`Revision ${version?.revision||p.revision} · ${p.status}`,btn('← Register','go-register')+btn('Print','print','primary')+(can('pi')&&['Draft','Awaiting LC'].includes(p.status)?btn('Revise','revise-pi','',`data-id="${p.id}"`):'')+(can('approve')&&['Draft','Awaiting LC'].includes(p.status)?btn('Cancel PI','cancel-pi','danger',`data-id="${p.id}"`):''))+`<div class="no-print toolbar">${select('Revision history','preview_revision',p.history.map(h=>[h.revision,'Revision '+h.revision+' · '+h.status]),version?.revision||p.revision)}<span class="muted">Snapshots preserve original recipe, rates and customer details.</span></div><article class="print-sheet"><div class="print-title"><h1>${esc(s.beneficiary.name)}</h1><p>${esc(s.beneficiary.address)}</p><h2>${esc(s.template.title)}</h2><p>Revision ${version?.revision||p.revision} · ${esc(version?.status||p.status)}</p></div><div class="detail-meta"><div><small>APPLICANT NAME</small><strong>${esc(s.customer.name)}</strong><br>${esc(s.customer.address)}</div><div><small>ADVISING BANK</small>${esc(s.beneficiary.bank)}<br>${esc(s.beneficiary.bank_address)}<br>SWIFT: ${esc(s.beneficiary.swift)}</div><div><small>PI NUMBER / DATE</small>${esc(p.number)} · Rev ${version?.revision||p.revision}<br>${esc(s.date)}<br>PO: ${esc(s.po_number||'—')}</div></div><p>Mode of Shipment: ${esc(s.beneficiary.shipment)}<br>Place of Loading: ${esc(s.beneficiary.loading)}<br>Final Destination: ${esc(s.beneficiary.destination)}</p><br>${table(['SL','Description of goods','H.S code','Quantity','Unit','Unit Price','Amount'],s.lines.map((l,i)=>`<tr><td>${i+1}</td><td><strong>${esc(l.product.name)}</strong><small>SIZE: ${l.inputs.l} × ${l.inputs.w} × ${l.inputs.h} CM</small></td><td>${esc(l.hs_code)}</td><td>${fmt(l.quantity,0)}</td><td>PCS</td><td>${fmt(l.unit_price,6)}</td><td>${fmt(l.amount)}</td></tr>`).join(''))}<div class="print-total">TOTAL: ${s.currency} ${fmt(total)}</div><p>AMOUNT IN WORDS: ${amountWords(total,s.currency)}</p><div class="print-terms">Payment terms: ${esc(s.payment_terms)}<br>${esc(s.beneficiary.terms)}<br>${esc(s.notes)}<br>${esc(s.template.notes)}</div><div class="signatures"><div>Confirm by the Buyer<br>Seal & Signature</div><div>For & behalf of:<br>${esc(s.beneficiary.name)}<br>(Authorized Signature)</div></div></article><section class="panel no-print"><div class="panel-head"><h2>Saved costing & batch traceability</h2></div>${s.lines.map(l=>`<div class="panel-body"><h3>${esc(l.product.name)} · recipe v${l.calculation.recipe_version}</h3>${calcResult(l.calculation)}</div>`).join('')}</section>`}
function words(n){if(n===0)return'zero';const a=['','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'],b=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];if(n<20)return a[n];if(n<100)return b[Math.floor(n/10)]+(n%10?' '+a[n%10]:'');if(n<1000)return a[Math.floor(n/100)]+' hundred'+(n%100?' '+words(n%100):'');for(const [v,l] of [[1e12,'trillion'],[1e9,'billion'],[1e6,'million'],[1000,'thousand']])if(n>=v)return words(Math.floor(n/v))+' '+l+(n%v?' '+words(n%v):'');return''}
function amountWords(value,currency){let [whole,cents]=Number(value).toFixed(2).split('.');return esc((words(Number(whole))+' '+currency+(Number(cents)?' and '+cents+'/100':'')+' only').toUpperCase())}
function productForm(p={}){modal(p.id?'Edit finished product':'Add finished product',`<div class="form-grid two"><input type="hidden" name="id" value="${p.id||''}">${field('Finished product name','name',p.name||'','text','required')}${field('H.S code','hs_code',p.hs_code||'')}${select('Counting unit','unit',['PCS','DZN','ROLL','KG'],p.unit||'PCS','required')}</div><p class="currency-note">Choose how this product is counted. Recipe quantity basis is configured separately.</p>`,p.id?'Save changes':'Save product','product-form')}
function manufacturing(){if(!tab)tab='Product Catalog';if(tab==='Recipe editor')return recipeEditor();let body='';if(tab==='Product Catalog')body=panel('Product Catalog','Names imported from the supplied Excel. Unapproved formulas are not enabled.',table(['Finished product','H.S code','Unit','Recipe',''],S.products.map(p=>{let r=S.recipes.find(x=>x.product_id===p.id);return `<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(p.hs_code||'—')}</td><td>${p.unit}</td><td>${r?badge(r.validated?'Verified · v'+r.version:'Sample required · v'+r.version):badge('Not configured')}</td><td>${can('recipe')?`<div class="table-actions">${btn('Edit product','product-edit','small-btn',`data-id="${p.id}"`)}${btn(r?'Edit recipe':'Set up recipe','recipe-edit','link',`data-product="${p.id}" ${r?`data-id="${r.id}"`:''}`)}</div>`:''}</td></tr>`}).join('')),can('recipe')?btn('+ Product','product-new','small-btn'):'');else if(tab==='Recipes & BOMs'||tab==='Recipe Versions')body=panel(tab,'Each saved change creates an immutable version; approved PI snapshots stay unchanged.',table(['Product','Version','Basis','Components','Status',''],S.recipes.map(r=>`<tr><td><strong>${esc(S.products.find(p=>p.id===r.product_id)?.name)}</strong></td><td>v${r.version}</td><td>${esc(r.config.basis==='per_piece'?'Per piece':'Batch of '+r.config.basis_pieces)}</td><td>${r.config.components.length} materials</td><td>${badge(r.validated?'Verified':'Sample required')}</td><td>${can('recipe')?btn('View / create version','recipe-edit','link',`data-id="${r.id}" data-product="${r.product_id}"`):''}</td></tr>`).join('')));else body=panel('Calculation Rules','Forms and dropdowns. No formula or code entry required.',`<div class="panel-body">${notice('For MASTER CARTOON 3 PLY: per-piece basis confirmed; order quantity is applied once. Glue formula approved from MANUFACTURING!J2.')}<div class="formula-preview">All dimensions in CM<br>Paper Length L = L1 + W1 + 6<br>Paper Width W = H1 + W1 + 2<br><br>Liner: ((L × W × Liner GSM × 2 × 2) / 10,000,000) × 1.08<br>Medium: ((L × 1.40 × W × Medium GSM × 1 × 2) / 10,000,000) × 1.08<br>Glue: (wastage-before liner kg + medium kg) × 20 / 1000 × 1.05<br><br>Each result × order quantity exactly once.</div><p class="currency-note">Other product rules must be explicitly configured and sample-verified before use.</p></div>`);return head('Manufacturing','Reusable product recipes, transparent calculations, controlled versions.')+tabs(['Product Catalog','Recipes & BOMs','Calculation Rules','Recipe Versions'])+body}
function recipeEditor(){let d=recipeDraft,parts=['l','w','h'],axes=['L','W','l','w','h'];return head('Recipe setup','Choose calculation steps. Save a new version, then verify a sample.',btn('← Recipes','recipes-back'))+notice('Original multipliers remain separate. Editing never changes an existing version or a saved PI.')+`<form id="recipe-form"><section class="panel form-section"><div class="section-title">01 · PRODUCT & DIMENSION RULES</div><div class="section-body form-grid">${field('Finished product','product_name',S.products.find(p=>p.id===d.product_id)?.name,'text','readonly')}${select('Calculation basis','basis',[['per_piece','Per piece'],['batch','Batch']],d.config.basis)}${field('Pieces per batch (only for batch basis)','basis_pieces',d.config.basis_pieces,'number','required')}${['L','W'].map(axis=>`<div class="span-all"><h3>Paper ${axis==='L'?'length L':'width W'} · CM</h3><div class="form-grid">${parts.map(p=>field(p.toUpperCase()+'1 factor',axis+'_factor_'+p,d.config.dimensions[axis].factors?.[p]??d.config.dimensions[axis].parts?.filter(x=>x===p).length??0,'number','required')).join('')}${field('Allowance · CM (may be negative)',axis+'_allowance',d.config.dimensions[axis].allowance,'number','required data-signed')}</div></div>`).join('')}${textarea('Version / change note','note',d.config.note)}</div></section><section class="panel form-section"><div class="section-title">02 · RAW MATERIAL CALCULATION STEPS</div><div class="section-body">${d.config.components.map((c,i)=>`<div class="recipe-component" data-component="${i}"><div class="actions"><h3>Material step ${i+1}</h3>${btn('Remove','recipe-remove','link',`data-index="${i}"`)}</div><div class="form-grid">${select('Raw material','material_id',S.materials.map(x=>[x.id,x.name]),c.material_id)}${select('Calculation type','kind',[['paper','Paper weight'],['glue','Glue from paper weight'],['fixed','Fixed kg per basis']],c.kind)}${c.kind==='paper'?select('First dimension','axis1',axes,c.axis1)+select('Second dimension','axis2',axes,c.axis2)+select('GSM source','gsm',[['liner_gsm','Liner GSM'],['medium_gsm','Medium GSM'],['gsm','GSM']],c.gsm)+field('Layer factor','layers',c.layers,'number','required')+field('Separate multiplier','multiplier',c.multiplier,'number','required')+field('Corrugation · %','corrugation',c.corrugation,'number','required')+field('Wastage · %','wastage',c.wastage,'number','required')+field('Unit conversion divisor','divisor',c.divisor,'number','required'):c.kind==='glue'?field('Glue grams per paper kg','grams_per_kg',c.grams_per_kg,'number','required')+field('Glue wastage · %','wastage',c.wastage,'number','required')+`<div class="span-all"><h3>Use these paper weights before wastage</h3>${d.config.components.filter(x=>x.kind==='paper').map(x=>`<label class="checkbox-label"><input type="checkbox" name="glue_source" value="${x.material_id}" ${(c.sources||[]).includes(Number(x.material_id))?'checked':''}>${esc(S.materials.find(m=>m.id===Number(x.material_id))?.name)}</label>`).join('')}</div>`:field('Quantity · KG per basis','quantity',c.quantity||'','number','required')}</div></div>`).join('')}<div class="form-footer">${btn('+ Add material step','recipe-add','small-btn')}</div><label class="checkbox-label"><input type="checkbox" name="complete" ${d.config.complete?'checked':''}>All required material components are included.</label></div><div class="form-footer"><button class="primary">Save as new recipe version</button></div><div class="error" hidden></div></section></form>${d.id?panel('Sample calculation verification','Compare with an independently checked sample before using this version.',`<form id="sample-form"><div class="panel-body"><div class="form-grid">${calcFields(sampleDefaults,false)}</div><div class="formula-preview" id="sample-result">${d.validated?'This version has a verified sample. Saving edits creates a new unverified version.':'Run a sample, then enter your independently checked expected totals in KG.'}</div><div class="form-footer">${btn('Preview sample','sample-preview','small-btn')}</div><div class="form-grid">${d.config.components.map(c=>field((S.materials.find(m=>m.id===Number(c.material_id))?.name||'Material')+' · expected KG','expected_'+c.material_id,'','number','required')).join('')}</div><div class="error" hidden></div></div><div class="form-footer"><span class="muted">Validates the saved version, not unsaved edits.</span><button class="primary">Verify saved recipe sample</button></div></form>`):notice('Save this recipe to enable sample verification.',true)}`}
function collectRecipe(){let f=$('#recipe-form'),d=Object.fromEntries(new FormData(f));let cfg=structuredClone(recipeDraft.config);cfg.basis=d.basis;cfg.basis_pieces=d.basis_pieces;cfg.note=d.note;cfg.complete=!!d.complete;for(let a of ['L','W'])cfg.dimensions[a]={factors:Object.fromEntries(['l','w','h'].map(p=>[p,d[a+'_factor_'+p]])),allowance:d[a+'_allowance']};cfg.components=[...f.querySelectorAll('[data-component]')].map(el=>{let c={};el.querySelectorAll('input,select').forEach(x=>{if(x.name==='glue_source')return;c[x.name]=x.value});c.material_id=Number(c.material_id);if(c.kind==='glue')c.sources=[...el.querySelectorAll('[name="glue_source"]:checked')].map(x=>Number(x.value));return c});recipeDraft.config=cfg;return cfg}
function inventory(){if(!tab)tab='Stock Overview';let content='';if(tab==='Stock Overview')content=panel('Stock Overview','On hand is physical stock. Reservations reduce available stock only.',table(['Raw material','On Hand · KG','Reserved · KG','Available · KG','Batches'],S.materials.map(m=>{let bs=S.batches.filter(b=>b.material_id===m.id),sum=k=>fmt(bs.reduce((n,b)=>n+Number(b[k]),0),4);return `<tr><td><strong>${esc(m.name)}</strong></td><td>${sum('on_hand')}</td><td>${sum('reserved')}</td><td>${sum('available')}</td><td>${bs.length}</td></tr>`}).join('')),can('stock')?btn('+ Raw material','material-new','small-btn'):'');else if(tab==='Stock In')content=`<form id="stock-form">${panel('Receive a material batch','Duplicate material + BoE + batch entries are rejected.',`<div class="panel-body form-grid">${select('Raw material','material_id',S.materials.map(m=>[m.id,m.name]))}${field('BoE number','boe','','text','required')}${field('Batch / lot number','batch','','text','required')}${field('Received date','received',today(),'date','required')}${field('Quantity · KG','quantity','','number','required')}${field('Unit cost per KG','unit_cost','','number','required')}${select('Cost currency','currency',['BDT','USD'],'BDT')}${field('Exchange rate · BDT per USD','fx','1','number','required')}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Save stock receipt</button></div>`)}</form>`;else if(tab==='Material Reservations')content=panel('Material Reservations','Explicit FIFO reservation. No physical stock deduction.',`${can('stock')?`<form id="reserve-form"><div class="toolbar">${select('Approved PI','pi_id',S.pis.filter(p=>['Awaiting LC','LC Created'].includes(p.status)).map(p=>[p.id,p.number]))}<button class="primary">Reserve materials</button></div><div class="error" hidden></div></form>`:''}${table(['PI number','Material','BoE / Batch','Reserved · KG','Status',''],S.reservations.map(r=>`<tr><td>${esc(r.pi_number)}</td><td>${esc(r.material)}</td><td>${esc(r.boe)} / ${esc(r.batch)}</td><td>${fmt(r.quantity,6)}</td><td>${badge(r.active?'Active':'Released')}</td><td>${can('stock')&&r.active?btn('Release PI reservations','release','link',`data-id="${r.pi_id}"`):''}</td></tr>`).join(''))}`);else if(tab==='Material Movements')content=panel('Material Movements','Stock receipts and reservation history. No consumption trigger is enabled.',table(['Date','Material','BoE / Batch','Movement','Quantity · KG','Reference'],S.movements.map(m=>`<tr><td>${esc(m.created.slice(0,10))}</td><td>${esc(m.material)}</td><td>${esc(m.boe)} / ${esc(m.batch)}</td><td>${badge(m.kind)}</td><td>${fmt(m.quantity,6)}</td><td>${esc(m.reference)}</td></tr>`).join('')));else content=panel('Batch Traceability','Trace batch receipts, reservations and saved PI costing.',table(['Material','BoE / Batch','Receipt','Cost / KG','Available · KG',''],S.batches.map(b=>`<tr><td>${esc(b.material)}</td><td>${esc(b.boe)} / ${esc(b.batch)}</td><td>${esc(b.received)}</td><td>${b.currency} ${fmt(b.unit_cost,4)}</td><td>${fmt(b.available,6)}</td><td>${btn('Trace batch →','batch-trace','link',`data-id="${b.id}"`)}</td></tr>`).join('')));return head('Inventory & stock','Every material. Every batch. A complete history.',can('stock')?btn('+ Stock In','tab','primary','data-tab="Stock In"'):'')+tabs(['Stock Overview',...(can('stock')?['Stock In']:[]),'Material Reservations','Material Movements','Batch Traceability'])+content}
function finance(){if(!tab)tab='Letters of Credit';if(tab==='Add LC')return lcEditor();let body='';if(tab==='Letters of Credit')body=panel('Letters of Credit','Drafts retain their PI in Awaiting LC. Confirmation creates the link.',table(['LC number','Linked PI','Customer','Amount','Outstanding','Status',''],S.lcs.map(l=>`<tr><td><strong>${esc(l.number)}</strong><small>${esc(l.details.lc_date)}</small></td><td>${esc(l.pi_number)}</td><td>${esc(l.details.pi_snapshot.customer.name)}</td><td>${l.currency} ${fmt(l.amount)}</td><td>${l.currency} ${fmt(l.outstanding)}</td><td>${badge(l.status)}</td><td>${l.status==='Draft'&&can('finance')?btn('Edit / confirm','lc-edit','link',`data-id="${l.id}"`):btn('Details','lc-details','link',`data-id="${l.id}"`)}</td></tr>`).join('')));else if(tab==='Maturity Schedule')body=panel('Maturity Schedule','Dates are entered explicitly; no assumed maturity basis.',table(['LC','Customer','LC date','Acceptance','Maturity','Outstanding','Status'],S.lcs.filter(l=>l.status==='Confirmed').sort((a,b)=>(a.details.maturity_date||'9999').localeCompare(b.details.maturity_date||'9999')).map(l=>`<tr><td>${esc(l.number)}</td><td>${esc(l.details.pi_snapshot.customer.name)}</td><td>${esc(l.details.lc_date)}</td><td>${esc(l.details.acceptance_date||'—')}</td><td>${esc(l.details.maturity_date||'Not entered')}</td><td>${l.currency} ${fmt(l.outstanding)}</td><td>${badge(Number(l.outstanding)===0?'Collected':l.details.maturity_date&&l.details.maturity_date<today()?'Overdue':'Outstanding')}</td></tr>`).join('')));else body=panel('Collections','Record partial collections in the LC currency.',`${can('finance')?`<form id="collection-form"><div class="panel-body form-grid">${select('Letter of Credit','lc_id',S.lcs.filter(l=>l.status==='Confirmed'&&Number(l.outstanding)>0).map(l=>[l.id,l.number+' · '+l.currency+' '+fmt(l.outstanding)+' due']))}${field('Collection amount · LC currency','amount','','number','required')}${field('Collection date','date',today(),'date','required')}${field('Bank / payment reference','reference','','text','required')}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Save collection</button></div></form>`:''}${table(['LC number','Currency','Date','Amount','Reference'],S.lcs.flatMap(l=>l.collections.map(c=>`<tr><td>${esc(l.number)}</td><td>${l.currency}</td><td>${esc(c.date)}</td><td>${fmt(c.amount)}</td><td>${esc(c.reference)}</td></tr>`)).join(''))}`);return head('Trade Finance','From an approved proforma to a collected payment.',can('finance')?btn('+ Add LC','add-lc','primary'):'')+tabs(['Letters of Credit',...(can('finance')?['Add LC']:[]),'Maturity Schedule','Collections'])+body}
let lcDraft=null;
function lcEditor(){let d=lcDraft||{},eligible=S.pis.filter(p=>p.status==='Awaiting LC'),p=S.pis.find(p=>p.id===Number(d.pi_id||eligible[0]?.id));return head('Add LC','Select an approved PI. Review inherited details, then save a draft or confirm.',btn('← Letters of Credit','tab','','data-tab="Letters of Credit"'))+(!eligible.length?notice('No PI is awaiting LC. Approve a draft Proforma first.',true):'')+`<form id="lc-form"><section class="panel form-section"><div class="section-title">01 · LINKED PROFORMA</div><div class="panel-body form-grid">${select('PI number','pi_id',eligible.map(p=>[p.id,p.number]),p?.id,'required')}${field('Customer','customer',p?.snapshot.customer.name||'','text','readonly')}${field('Beneficiary','beneficiary',p?.snapshot.beneficiary.name||'','text','readonly')}${field('Currency','currency',p?.currency||'','text','readonly')}${field('PI amount','pi_amount',p?.total||'','text','readonly')}${field('Payment terms','payment_terms',p?.snapshot.payment_terms||'','text','readonly')}</div>${p?table(['Product','Size CM','Quantity','Unit price','Amount'],p.snapshot.lines.map(l=>`<tr><td>${esc(l.product.name)}</td><td>${l.inputs.l} × ${l.inputs.w} × ${l.inputs.h}</td><td>${fmt(l.quantity,0)} PCS</td><td>${fmt(l.unit_price,6)}</td><td>${fmt(l.amount)}</td></tr>`).join('')):''}</section><section class="panel form-section"><div class="section-title">02 · LC DETAILS & REFERENCES</div><div class="panel-body form-grid">${field('LC number','number',d.number||'','text','required')}${field('LC date','lc_date',d.lc_date||today(),'date','required')}${field('Bank','bank',d.bank||'','text','required')}${field('Branch','branch',d.branch||'')}${field('LC amount · '+(p?.currency||''),'amount',d.amount||p?.total||'','number','required')}${field('Tenor / duration','tenor',d.tenor||'')}${field('Forwarding date','forwarding_date',d.forwarding_date||'','date')}${field('Acceptance date','acceptance_date',d.acceptance_date||'','date')}${field('Maturity date · explicit','maturity_date',d.maturity_date||'','date')}${field('Bank reference number','bank_reference',d.bank_reference||'')}${field('UP number','up_number',d.up_number||'')}${field('UP date','up_date',d.up_date||'','date')}${field('Applicant via party','via_party',d.via_party||'')}${field('Beneficiary account number','beneficiary_account',d.beneficiary_account||p?.snapshot.beneficiary.account||'')}${select('Save status','status',['Draft','Confirmed'],d.status||'Draft')}${textarea('Comments / references','comments',d.comments||'')}<div class="error span-all" hidden></div></div><div class="form-footer"><span class="muted">Confirmed → PI status LC Created. PI is retained.</span><button class="primary" ${p?'':'disabled'}>Save LC</button></div></section></form>`}
const REPORTS=['Customer-wise Sales','Stock','Costing','Collection','LC','PI Reports'];let reportRows=[],reportHeaders=[];
function reports(){if(!REPORTS.includes(tab))tab='Customer-wise Sales';let h=[],r=[];if(tab==='Customer-wise Sales'){h=['Customer','Currency','Approved / linked PI count','Proforma value'];for(const c of S.customers)for(const cur of ['BDT','USD']){let ps=S.pis.filter(p=>p.customer_id===c.id&&p.currency===cur&&['Awaiting LC','LC Created'].includes(p.status));if(ps.length)r.push([c.name,cur,ps.length,fmt(ps.reduce((n,p)=>n+Number(p.total),0))])}}else if(tab==='Stock'){h=['Material','BoE','Batch','Currency','Unit cost','On Hand KG','Reserved KG','Available KG'];r=S.batches.map(b=>[b.material,b.boe,b.batch,b.currency,b.unit_cost,b.on_hand,b.reserved,b.available])}else if(tab==='Costing'){h=['PI','Revision','Product','Recipe version','Currency','FX BDT per USD','Quantity PCS','Material cost BDT','Markup %','Unit Price'];r=S.pis.flatMap(p=>p.snapshot.lines.map(l=>[p.number,p.revision,l.product.name,l.calculation.recipe_version,p.currency,l.inputs.fx,l.quantity,l.calculation.cost_bdt,l.inputs.markup,l.unit_price]))}else if(tab==='Collection'){h=['LC','Customer','Currency','LC amount','Collected','Outstanding','Maturity'];r=S.lcs.filter(l=>l.status==='Confirmed').map(l=>[l.number,l.details.pi_snapshot.customer.name,l.currency,l.amount,l.collected,l.outstanding,l.details.maturity_date||'Not entered'])}else if(tab==='LC'){h=['LC','PI','Currency','Amount','Status','Bank','LC date','Maturity'];r=S.lcs.map(l=>[l.number,l.pi_number,l.currency,l.amount,l.status,l.details.bank,l.details.lc_date,l.details.maturity_date||'Not entered'])}else{h=['PI','Revision','Customer','Date','Currency','Amount','Status'];r=S.pis.map(p=>[p.number,p.revision,p.snapshot.customer.name,p.snapshot.date,p.currency,p.total,p.status])}reportRows=r;reportHeaders=h;return head('Reports','Traceable reports from saved records. USD and BDT stay separate.',btn('↓ Export CSV','export-report'))+tabs(REPORTS)+(tab==='Customer-wise Sales'?notice('This report shows approved proforma values by customer; it is not a shipment or recognized-revenue ledger.'):'')+panel(tab,`${r.length} records`,table(h,r.map(row=>'<tr>'+row.map(v=>`<td>${esc(v)}</td>`).join('')+'</tr>').join('')))}
function admin(){if(!can('admin'))return head('Administration','Your role does not have administration permissions.');if(!tab)tab='Company Settings';let body='';if(tab==='Company Settings'||tab==='Numbering'){let c=S.company;body=`<form id="settings-form" data-key="company">${panel(tab,tab==='Numbering'?'Unique sequence assigned atomically on save. Revisions retain the original PI number.':'Company details from the supplied workbook. Review before issuing documents.',`<div class="panel-body form-grid">${Object.entries({name:'Company / beneficiary name',address:'Company address',bank:'Advising bank',bank_address:'Bank / branch address',swift:'SWIFT',account:'Beneficiary account',prefix:'PI numbering prefix',shipment:'Mode of shipment',loading:'Place of loading',destination:'Final destination'}).map(([k,label])=>field(label,k,c[k]||'','text',['name','prefix'].includes(k)?'required':'')).join('')}${textarea('Default commercial terms · explicitly review before use','terms',c.terms)}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Save settings</button></div>`)}</form>`}else if(tab==='Document Templates')body=`<form id="settings-form" data-key="template">${panel('Document Templates','Based on PRINT PI: company header, applicant/bank, goods table, totals, terms and signatures.',`<div class="panel-body form-grid">${field('Document title','title',S.template.title,'text','required')}${textarea('Additional print notes','notes',S.template.notes)}<div class="error span-all" hidden></div></div><div class="form-footer"><button class="primary">Save template</button></div>`)}</form>`;else if(tab==='Users & Roles')body=panel('Users & Roles','Permissions are enforced by the server for every save.',table(['Name','Username','Role','Status',''],S.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${badge(u.active?'Active':'Disabled')}</td><td>${btn('Edit access','user-edit','link',`data-id="${u.id}"`)}</td></tr>`).join(''))+`<div class="panel-body">${table(['Role','Allowed actions'],Object.entries(S.roles).map(([role,perms])=>`<tr><td>${esc(role)}</td><td>${esc(perms.join(', ')||'Read only')}</td></tr>`).join(''))}</div>`,btn('+ User','user-new','small-btn'));else body=panel('Audit Trail','Append-only business action log. Latest 300 entries.',table(['Time · UTC','User','Action','Record',''],S.audit.map(a=>`<tr><td>${esc(a.created.slice(0,19).replace('T',' '))}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td><td>${btn('Details','audit-details','link',`data-id="${a.id}"`)}</td></tr>`).join('')));return head('Administration','Company identity, access control and document settings.')+tabs(['Company Settings','Users & Roles','Document Templates','Numbering','Audit Trail'])+body}
function userForm(u={}){modal(u.id?'Edit user access':'Add user',`<div class="form-grid two"><input type="hidden" name="id" value="${u.id||''}">${field('Full name','name',u.name||'','text','required')}${field('Username','username',u.username||'','text',u.id?'readonly':'required')}${field(u.id?'New password · leave blank to retain':'Password · 15–128 characters','password','','password',u.id?'minlength="15" maxlength="128"':'required minlength="15" maxlength="128"')}${select('Role','role',Object.keys(S.roles),u.role||'Viewer')}${select('Account status','active',[[1,'Active'],[0,'Disabled']],u.active??1)}${S.security?.admin_verification_required?field('Your current Admin password','actor_password','','password','required autocomplete="current-password"')+field('Your fresh authenticator / recovery code','actor_code','','text','required maxlength="32" autocomplete="one-time-code"'):''}</div>`,'Save user','user-form')}
function getPiDraft(){let f=$('#pi-form');if(!f)return;let d=Object.fromEntries(new FormData(f));for(let k of ['customer_id','date','currency','fx','po_number','payment_terms','notes','hs_code'])piDraft[k]=d[k];piDraft.calc={};for(let k of ['recipe_id','l','w','h','liner_gsm','medium_gsm','gsm','quantity','markup'])piDraft.calc[k]=d[k];return {...piDraft.calc,currency:d.currency,fx:d.fx,pi_id:piDraft.id||null,prior_calculations:piDraft.lines.map(l=>l.calculation_id)}}
function bindPage(){let stockCurrency=$('#stock-form [name="currency"]');if(stockCurrency)stockCurrency.addEventListener('change',()=>{$('#stock-form [name="fx"]').value=stockCurrency.value==='USD'?'':'1'});let f=$('#pi-form');let recipeSelect=f?.querySelector('[name="recipe_id"]');if(recipeSelect)recipeSelect.addEventListener('change',()=>updateGsmRequirements(f,S.recipes.find(r=>r.id===Number(recipeSelect.value))?.config));if(f)f.addEventListener('input',e=>{if(e.target.name==='currency'){f.querySelector('[name="fx"]').value=e.target.value==='USD'?'':'1'}getPiDraft();if(e.target.closest('#calc-inputs')||['currency','fx'].includes(e.target.name)){lastCalc=null;let up=f.querySelector('[name="unit_price"]');up.value='';f.querySelector('[data-action="add-line"]').disabled=true;$('#calc-result').innerHTML=notice('Inputs changed. Calculate Unit Price again.',true);if(['currency','fx'].includes(e.target.name)&&piDraft.lines.length){piDraft.lines=[];render();toast('Currency or rate changed. Recalculate and add every line again.')}}});let lc=$('#lc-form [name="pi_id"]');if(lc)lc.addEventListener('change',()=>{lcDraft={pi_id:lc.value};render()});let preview=$('[name="preview_revision"]');if(preview)preview.addEventListener('change',()=>{piDraft.previewRevision=preview.value;render()});document.querySelectorAll('[data-component] [name="kind"]').forEach(x=>x.addEventListener('change',()=>{let cfg=collectRecipe(),c=cfg.components[Number(x.closest('[data-component]').dataset.component)];Object.assign(c,c.kind==='paper'?{axis1:'L',axis2:'W',gsm:'gsm',layers:'1',multiplier:'1',corrugation:'0',wastage:'0',divisor:'10000000'}:c.kind==='glue'?{grams_per_kg:'',wastage:'0',sources:[]}: {quantity:''});render()}))}
function navigate(p,t=''){page=p;tab=t;lastCalc=null;render();window.scrollTo(0,0)}
async function saveAction(route,data,message){await api(route,data);toast(message);await refresh()}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);try{switch(a){case'hide-recovery':securityRecoveryCodes=[];showSecurity();break;case'account-security':showSecurity();break;case'mfa-restart':securityEnrollment=null;showSecurity();break;case'download-recovery':{let url=URL.createObjectURL(new Blob(['Satata ERP recovery codes — keep private\n'+securityRecoveryCodes.join('\n')],{type:'text/plain'})),download=document.createElement('a');download.href=url;download.download='satata-erp-recovery-codes.txt';download.click();setTimeout(()=>URL.revokeObjectURL(url),500);break}case'nav':navigate(b.dataset.page);break;case'tab':if($('#pi-form'))getPiDraft();tab=b.dataset.tab;if(tab==='Unit Price Calculation'){piDraft=null;lastCalc=null}if(tab==='Add LC')lcDraft=null;render();break;case'logout':await api('/api/logout',{});S=null;auth(false);break;case'close':close();break;case'create-pi':piDraft=null;lastCalc=null;navigate('Proforma Invoices','Create Proforma');break;case'go-register':navigate('Proforma Invoices','PI Register');break;case'go-finance':navigate('Trade Finance','Letters of Credit');break;case'pi-filter':piFilter=b.dataset.filter;render();break;case'customer-new':customerForm();break;case'customer-edit':close();customerForm(S.customers.find(x=>x.id===id));break;case'customer-profile':customerProfile(id);break;case'calculate':{let f=$('#pi-form');let inputs=getPiDraft();if(!f.querySelector('[name="recipe_id"]').value)throw new Error('Set up a recipe first.');b.disabled=true;lastCalc=await api('/api/calculate',inputs);render();break}case'add-line':{if(!lastCalc?.ready)throw new Error('Calculate a valid price first');let inputs=getPiDraft(),r=S.recipes.find(r=>r.id===Number(inputs.recipe_id));piDraft.lines.push({calculation_id:lastCalc.calculation_id,hs_code:piDraft.hs_code,inputs:structuredClone(inputs),result:lastCalc,product:S.products.find(p=>p.id===r.product_id).name});lastCalc=null;render();break}case'remove-line':getPiDraft();piDraft.lines.splice(Number(b.dataset.index),1);render();break;case'preview':close();piDraft={previewId:id};navigate('Proforma Invoices','Preview');break;case'print':window.print();break;case'approve':await saveAction('/api/pis/approve',{id},'PI approved · Awaiting LC');break;case'cancel-pi':modal('Cancel Proforma',notice('This preserves the PI and its revision history. Reservations will be released. Confirm cancellation below.')+`<input type="hidden" name="id" value="${id}">`,'Cancel this PI','cancel-pi-form');break;case'revise-pi':{let p=S.pis.find(p=>p.id===id);piDraft={id,expected_revision:p.revision,customer_id:p.customer_id,...p.snapshot,lines:[],calc:p.snapshot.lines[0]?.inputs};lastCalc=null;tab='Create Proforma';render();toast('Recalculate and add each line for the new revision.');break}case'product-new':productForm();break;case'product-edit':productForm(S.products.find(p=>p.id===id));break;case'material-new':modal('Add raw material',field('Material name · stock unit KG','name','','text','required'),'Save material','material-form');break;case'recipe-edit':{let r=S.recipes.find(r=>r.id===id);recipeDraft=r?structuredClone(r):{product_id:Number(b.dataset.product),config:{basis:'per_piece',basis_pieces:'1',dimensions:{L:{parts:['l'],allowance:'0'},W:{parts:['w'],allowance:'0'}},components:[],complete:false,note:''}};tab='Recipe editor';render();break}case'recipes-back':tab='Recipes & BOMs';render();break;case'recipe-add':collectRecipe();recipeDraft.config.components.push({material_id:S.materials[0]?.id,kind:'paper',gsm:'gsm',axis1:'L',axis2:'W',layers:'1',multiplier:'1',corrugation:'0',wastage:'0',divisor:'10000000'});render();break;case'recipe-remove':collectRecipe();recipeDraft.config.components.splice(Number(b.dataset.index),1);render();break;case'sample-preview':{let d=Object.fromEntries(new FormData($('#sample-form'))),r=await api('/api/sample',{...d,recipe_id:recipeDraft.id});$('#sample-result').textContent='Saved recipe sample: '+Object.entries(r.dimensions).map(([k,v])=>k+' = '+v+' CM').join(' · ')+'\n'+r.materials.map(x=>S.materials.find(m=>m.id===x.material_id).name+': '+x.required+' KG').join('\n');break}case'release':await saveAction('/api/reservations/release',{pi_id:id},'Reservations released; physical stock unchanged');break;case'batch-trace':{let bs=S.batches.find(x=>x.id===id),links=S.pis.flatMap(p=>p.history.flatMap(h=>h.snapshot.lines.filter(l=>l.calculation.materials.some(m=>m.allocations.some(x=>x.batch_id===id))).map(l=>[p.number,h.revision,l.product.name,l.calculation.recipe_version])));modal('Batch Traceability',`<h3>${esc(bs.material)}</h3><p>BoE ${esc(bs.boe)} · Batch ${esc(bs.batch)} · ${bs.currency} ${fmt(bs.unit_cost,4)} / KG · FX ${bs.fx}</p><br>${table(['PI','Revision','Product','Recipe'],links.map(r=>'<tr>'+r.map(v=>`<td>${esc(v)}</td>`).join('')+'</tr>').join(''))}${table(['Movement','Quantity KG','Reference','Date'],S.movements.filter(x=>x.batch_id===id).map(x=>`<tr><td>${esc(x.kind)}</td><td>${fmt(x.quantity,6)}</td><td>${esc(x.reference)}</td><td>${esc(x.created.slice(0,10))}</td></tr>`).join(''))}`);break}case'add-lc':lcDraft=id?{pi_id:id}:null;navigate('Trade Finance','Add LC');break;case'lc-edit':{let l=S.lcs.find(x=>x.id===id);lcDraft={...l.details,...l};navigate('Trade Finance','Add LC');break}case'lc-details':{let l=S.lcs.find(x=>x.id===id);modal('Letter of Credit',`<div class="detail-meta">${[['LC number',l.number],['PI number',l.pi_number],['Customer',l.details.pi_snapshot.customer.name],['Beneficiary',l.details.pi_snapshot.beneficiary.name],['Payment terms',l.details.pi_snapshot.payment_terms],['Currency',l.currency],['LC amount',fmt(l.amount)],['Outstanding',fmt(l.outstanding)],['Bank',l.details.bank],['Maturity',l.details.maturity_date||'Not entered'],['Reference',l.details.bank_reference]].map(([k,v])=>`<div><small>${k}</small>${esc(v)}</div>`).join('')}</div>`);break}case'user-new':userForm();break;case'user-edit':userForm(S.users.find(x=>x.id===id));break;case'audit-details':{let x=S.audit.find(x=>x.id===id);modal('Audit detail',`<h3>${esc(x.action)} · ${esc(x.actor)}</h3><pre class="formula-preview">${esc(JSON.stringify(JSON.parse(x.detail),null,2))}</pre>`);break}case'export-report':{const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';let csv='\ufeff'+[reportHeaders,...visibleReportRows()].map(r=>r.map(cell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=tab.toLowerCase().replaceAll(' ','-')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);break}}}catch(error){showError(error,b.closest('form'));}finally{if(b.isConnected)b.disabled=false}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button[type="submit"],button.primary:not([type="button"])');if(f.dataset.busy)return;f.dataset.busy='1';if(button)button.disabled=true;let d=Object.fromEntries(new FormData(f));try{let route='',payload=d,message='Saved';switch(f.id){case'auth-form':{let r=await api(f.dataset.setup==='true'?'/api/setup':'/api/login',d);csrf=r.csrf;if(r.mfa_enrollment_required){securityUser=r.user;S=null;mfaSetupRequired=true;showSecurity()}else await refresh();return}case'mfa-enroll-form':securityEnrollment=await api('/api/security/mfa/enroll',d);showSecurity();return;case'mfa-confirm-form':{let r=await api('/api/security/mfa/confirm',d);csrf=r.csrf;securityRecoveryCodes=r.recovery_codes;securityEnrollment=null;mfaSetupRequired=false;S=await api('/api/state');page='Account security';render();toast('Authenticator verification enabled');return}case'password-form':{let r=await api('/api/security/password',d);csrf=r.csrf;securityRecoveryCodes=[];await refresh();toast('Password changed; other devices signed out');return}case'customer-form':route='/api/customers';if(!d.id)delete d.id;message='Customer saved';break;case'product-form':route='/api/products';if(!d.id)delete d.id;message=d.id?'Product updated':'Product saved';break;case'material-form':route='/api/materials';message='Material saved';break;case'stock-form':route='/api/stock-in';message='Stock receipt saved';break;case'pi-form':{getPiDraft();route='/api/pis';payload={...piDraft,lines:piDraft.lines.map(l=>({calculation_id:l.calculation_id,hs_code:l.hs_code,inputs:l.inputs}))};message='Proforma saved as draft';break}case'cancel-pi-form':route='/api/pis/cancel';message='Proforma cancelled';break;case'recipe-form':route='/api/recipes';payload={product_id:recipeDraft.product_id,config:collectRecipe()};message='New recipe version created · verify its sample';break;case'sample-form':{route='/api/recipes/validate';let expected={};for(let [k,v] of Object.entries(d))if(k.startsWith('expected_'))expected[k.slice(9)]=v;payload={recipe_id:recipeDraft.id,inputs:d,expected};message='Saved recipe sample verified';break}case'reserve-form':route='/api/reserve';message='Materials reserved · physical stock unchanged';break;case'lc-form':route='/api/lcs';payload={...d,...(lcDraft?.id?{id:lcDraft.id}:{})};message=d.status==='Confirmed'?'LC confirmed · PI moved to LC Created':'LC draft saved · PI remains Awaiting LC';break;case'collection-form':route='/api/collections';message='Partial collection recorded';break;case'settings-form':route='/api/settings';payload={key:f.dataset.key,value:d};message='Settings saved';break;case'user-form':route='/api/users';payload={...d,active:d.active==='1'};if(!d.id)delete payload.id;message='User access saved';break;default:return}const result=await api(route,payload,f.dataset.saveKey||(f.dataset.saveKey=crypto.randomUUID()));close();if(f.id==='pi-form'){piDraft={previewId:result.id};tab='Preview'}if(f.id==='lc-form'){tab='Letters of Credit';lcDraft=null}if(f.id==='recipe-form'){S=await api('/api/state');recipeDraft=structuredClone(S.recipes.find(r=>r.id===result.id));tab='Recipe editor';render()}else if(f.id==='sample-form'){S=await api('/api/state');recipeDraft=structuredClone(S.recipes.find(r=>r.id===recipeDraft.id));render()}else await refresh();toast(message)}catch(error){showError(error,f)}finally{delete f.dataset.busy;if(button?.isConnected)button.disabled=false}});
(async()=>{try{let s=await api('/api/session');if(s.setup_required)auth(true,s.setup_token_required);else{csrf=s.csrf;if(s.mfa_enrollment_required){securityUser=s.user;mfaSetupRequired=true;showSecurity()}else await refresh()}}catch(e){auth(false)}})();
